        private static void lBuildTrans_S1F1(SecsTransaction Trans)
        {
            SecsMessage Msg;
            SecsItem PItem;
            SecsItem NItem;


            Msg = Trans.Primary;
            Msg.Name = "R";
            Msg.Description = "Are you there request";
            Msg.Function = 1;
            Msg.Stream = 1;
            Msg = Trans.Secondary;
            Msg.Name = "D";
            Msg.Description = "On line data";
            Msg.Function = 2;
            Msg.Stream = 1;
            PItem = Msg.Root;
            PItem.AddNew(1);
            NItem = PItem.Item[1];
            NItem.Name = "L";
            NItem.Description = "";
            NItem.Format = FormatConstants.wsFormatList;
            NItem.NLB = 0;
            PItem = Msg.Root.Item[1];
            PItem.AddNew(1);
            NItem = PItem.Item[1];
            NItem.Name = "MDLN";
            NItem.Description = "Equipment Model Type";
            NItem.Format = FormatConstants.wsFormatAscii;
            NItem.NLB = 0;
            PItem = Msg.Root.Item[1];
            PItem.AddNew(2);
            NItem = PItem.Item[2];
            NItem.Name = "SOFTREV";
            NItem.Description = "Software Revision Code";
            NItem.Format = FormatConstants.wsFormatAscii;
            NItem.NLB = 0;
        }

